<?php declare(strict_types=1);
$revision=input($_GET,'clearing_original');$sha=input($_GET,'clearing_original_sha256');
try{if(!preg_match('/\A[1-9][0-9]{0,3}\z/D',$revision))throw new DomainException('Ursprünglichen Verrechnungsnachweis vollständig auswählen.',422);$originalDetails=$service->originalDetails($year,(int)$revision,$sha);$original=$originalDetails['original'];$proof=$original['proof'];}
catch(DomainException|JsonException$ex){if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,422],true)?$ex->getCode():403);echo '<p role="alert">'.e($clearingText($ex->getMessage())).'</p>';return;}
$originalMoney=static fn(int$n):string=>number_format($n/100,2,',','.').' €';$originalDate=static fn(string$d):string=>implode('.',array_reverse(explode('-',$d)));
$originalSources=array_column($originalDetails['segments']['journal']['entries'],null,'id');$originalUnits=$proof['units'];
$current=null;$currentError='';try{$current=$service->get($year);}catch(DomainException|JsonException$ex){$currentError=$ex->getMessage();}
$currentLabel=$current===null?'Aktuellen Zahlenstand getrennt prüfen':(!$current['source_current']?'Geänderte Buchungsaufteilung erneut prüfen':(!$current['carry_current']?'Vorjahresnachweis erneut abstimmen':($current['current_approval']?'Aktuell geprüft':'Aktuelle Prüfung noch offen')));
?>
<link rel="stylesheet" href="tax-guided.css?v=3"><div class="content" data-tax-guided>
<div class="page-heading"><h1><?= e($clearingText('Verrechnungsnachweis')) ?> · <?= $year ?></h1></div>
<section class="card" data-balance-clearing-original="<?= e($original['sha256']) ?>" data-clearing-revision="<?= (int)$original['revision'] ?>">
<p role="status"><strong><?= e($clearingText($original['state']==='reviewed'?'Dieser Verrechnungsnachweis wurde damals vom Vorstand bestätigt.':'Dieser Verrechnungsnachweis wurde damals zur gesonderten Prüfung vorbereitet.')) ?></strong></p>
<dl><dt><?= e($clearingText('Damals angenommen am')) ?></dt><dd><?= e((new DateTimeImmutable($original['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i')) ?></dd><dt><?= e($clearingText('Ursprünglicher Vermerk')) ?></dt><dd><?= e($original['note']) ?></dd></dl>
<details><summary><?= e($clearingText('Damals geprüfte Vorschüsse, Rückzahlungen und Quellen')) ?></summary>
<dl><?php foreach(['opening_cents'=>'Aus dem Vorjahr offen','advanced_cents'=>'Im Jahr vorgestreckt','repaid_cents'=>'Im Jahr zurückgezahlt','closing_cents'=>'Am Jahresende noch offen']as$key=>$caption): ?><dt><?= e($clearingText($caption)) ?></dt><dd><?= $originalMoney($proof['totals'][$key]) ?></dd><?php endforeach ?></dl>
<?php foreach($proof['cases']as$case): ?><article><h2><?= e($originalUnits[$case['from']]['name'].' → '.$originalUnits[$case['to']]['name']) ?></h2><p><?= (int)$case['origin_year'] ?> · <?= e($clearingText('Ursprünglich vorgestreckt')) ?> <?= $originalMoney($case['original_cents']) ?> · <?= e($clearingText('Im Jahr zurückgezahlt')) ?> <?= $originalMoney($case['repaid_cents']) ?> · <?= e($clearingText('Noch offen')) ?> <?= $originalMoney($case['closing_cents']) ?></p><p><?= e($clearingText('Rückzahlung vereinbart bis')) ?> <?= e($originalDate($case['repay_by'])) ?></p></article><?php endforeach ?>
<?php foreach($proof['instructions']as$kind=>$rows):foreach($rows as$row):$source=$originalSources[$row['voucher']]; ?><article><h3><?= e($clearingText($kind==='advances'?'Vorschuss':'Rückzahlung')) ?> · <?= $originalMoney($row['cents']) ?></h3><p><?= e($originalDate($source['date']).' · '.$source['description']) ?></p><p><?= e($row['reason']) ?></p></article><?php endforeach;endforeach ?>
<?php if($original['carry_source']!==null):$prior=$original['carry_source']; ?><p><a class="btn btn-outline" data-clearing-original-prior href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$prior['year'],'clearings'=>'1','clearing_original'=>(string)$prior['revision'],'clearing_original_sha256'=>$prior['sha256']])) ?>"><?= e($clearingText('Damals übernommenen Vorjahresnachweis öffnen')) ?></a></p><?php endif ?>
<p><a class="btn btn-outline" data-clearing-original-allocation href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','balance_year'=>(string)$year,'segments'=>'1','segment_original'=>(string)$original['segment_source']['revision'],'segment_original_sha256'=>$original['segment_source']['sha256']])) ?>"><?= e($clearingText('Ursprüngliche Buchungsaufteilung öffnen')) ?></a></p>
</details></section>
<section class="card"><h2><?= e($clearingText('Aktueller Stand des Verrechnungsnachweises')) ?></h2><p><?= e($clearingText($currentLabel)) ?></p><?php if($currentError!==''): ?><p role="alert"><?= e($clearingText($currentError)) ?></p><?php endif ?><a class="btn btn-outline" href="<?= e(url($clearingHome)) ?>"><?= e($clearingText('Aktuellen Verrechnungsnachweis öffnen')) ?></a></section>
</div>
